namespace Joomla\Registry {
    /** Standalone replacement of the Registry data parser. */
    final class Registry
    {
        public static int $loads = 0;

        /**
         * Interpret JSON fixture settings without the Joomla runtime.
         *
         * @param string $data JSON payload supplied by the caller.
         * @return void
         */
        public function loadString(string $data): void
        {
            ++self::$loads;
            $this->decoded = json_decode($data, true, 32, JSON_THROW_ON_ERROR);
        }

        private mixed $decoded = null;

        /**
         * Return the decoded values for the site helper contract.
         *
         * @return mixed Parsed fixture data, including malformed scalar values.
         */
        public function toArray(): mixed
        {
            return $this->decoded;
        }
    }
}

namespace Joomla\CMS\Installer {
    /** Supply controlled SQL query splitting fixtures. */
    final class Installer
    {
        public static mixed $statements = [];

        /**
         * Return the configured statement records for SQL import tests.
         *
         * @param string $sql Raw SQL script source.
         * @return mixed Fixture statement list.
         */
        public static function splitSql(string $sql): mixed
        {
            return self::$statements;
        }
    }
}

namespace Joomla\Database {
    /** Minimal Joomla database contract used by the SQL import test. */
    interface DatabaseInterface
    {
        /**
         * Record the SQL statement for a test database.
         *
         * @param string $statement SQL query to execute.
         * @return self Fluent query execution interface.
         */
        public function setQuery(string $statement): self;

        /**
         * Simulate execution of the prepared SQL statement.
         *
         * @return bool Whether the test statement executed.
         */
        public function execute(): bool;
    }
}

namespace Joomla\CMS\Language {
    /** Return deterministic standalone translations for the module layout. */
    final class Text
    {
        /**
         * Return a translation key without loading Joomla language files.
         *
         * @param string $key Requested language translation.
         * @return string Same key for assertions.
         */
        public static function _(string $key): string
        {
            return $key;
        }
    }
}

namespace {
    define('_JEXEC', 1);
    $root = dirname(__DIR__, 2);
    require_once $root . '/site/src/Helper/ExtendedDataHelper.php';
    require_once $root . '/admin/src/Helper/SqlImportHelper.php';

    $extended = \Diddipoeler\Component\SportsManagement\Site\Helper\ExtendedDataHelper::class;
    if ($extended::toArray('{"name":"test"}') !== ['name' => 'test']
        || $extended::toArray('123') !== []
        || $extended::toArray('{bad json') !== []) {
        throw new \RuntimeException('Site extended-data parser did not handle valid and malformed data.');
    }

    \Joomla\Registry\Registry::$loads = 0;
    if ($extended::toArray(str_repeat('x', 1048577)) !== []
        || \Joomla\Registry\Registry::$loads !== 0) {
        throw new \RuntimeException('Oversized extended-data input reached Joomla Registry.');
    }

    $database = new class implements \Joomla\Database\DatabaseInterface {
        public array $queries = [];

        /**
         * Save the statement that the importer prepares for execution.
         *
         * @param string $statement Statement generated by the SQL parser.
         * @return self Current test driver.
         */
        public function setQuery(string $statement): self
        {
            $this->queries[] = $statement;
            return $this;
        }

        /**
         * Confirm that the test query was accepted for execution.
         *
         * @return bool Successful simulated SQL execution.
         */
        public function execute(): bool
        {
            return true;
        }
    };

    $filename = tempnam(sys_get_temp_dir(), 'sm-sql-');
    if ($filename === false) {
        throw new \RuntimeException('Unable to allocate SQL test fixture.');
    }

    file_put_contents($filename, 'CREATE TABLE #__dummy (id int);');

    try {
        $importer = \Diddipoeler\Component\SportsManagement\Administrator\Helper\SqlImportHelper::class;
        \Joomla\CMS\Installer\Installer::$statements = [
            ['query' => 'CREATE TABLE #__dummy (id int)'],
            ' INSERT INTO #__dummy VALUES (1) ',
            '',
        ];
        $importer::importFile($database, $filename);

        if ($database->queries !== [
            'CREATE TABLE #__dummy (id int)',
            'INSERT INTO #__dummy VALUES (1)',
        ]) {
            throw new \RuntimeException('Valid SQL import records were not executed in order.');
        }

        foreach ([['query' => ['malformed']], [false], (object) ['query' => 'SELECT 1']] as $malformed) {
            \Joomla\CMS\Installer\Installer::$statements = [$malformed];
            try {
                $importer::importFile($database, $filename);
                throw new \RuntimeException('Malformed SQL parser result must fail the import.');
            } catch (\RuntimeException $e) {
                if ($e->getMessage() === 'Malformed SQL parser result must fail the import.') {
                    throw $e;
                }
            }
        }
    } finally {
        unlink($filename);
    }

    $params = new class {
        /**
         * Supply default module layout values during the empty-row test.
         *
         * @param string $key Module parameter identifier.
         * @param mixed $default Default parameter value.
         * @return mixed Unchanged module parameter default.
         */
        public function get(string $key, mixed $default = null): mixed
        {
            return $default;
        }
    };

    foreach ([['player' => ['bad' => true]], ['player' => 123], ['player' => null]] as $list) {
        ob_start();
        require $root . '/modules/mod_sportsmanagement_randomplayer/tmpl/native.php';
        $output = (string) ob_get_clean();
        if (!str_contains($output, 'NO ITEMS')) {
            throw new \RuntimeException('Malformed player rows should use the empty state.');
        }
    }

    echo "Joomla 5/6 extended data, SQL imports and RandomPlayer malformed rows: OK\n";
}
